package problema4;

import java.util.List;

public class Parking {
    private List<Plaza> plazas;

    public Parking(int numPlazas, int numPlazasVip) {
        plazas = new java.util.ArrayList<>(numPlazas);
        for (int i = 0; i < numPlazas; i++) {
            boolean esVip = i < numPlazasVip;
            plazas.add(new Plaza(i + 1, esVip));
        }
    }

}

package problema4;

import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public class Parking {
    private final int plazasNormales;
    private final int plazasVip;
    private final int capacidadCola;

    private int ocupadasNormales = 0;
    private int ocupadasVip = 0;

    private final Queue<Coche> colaEspera;

    public Parking(int numPlazas, int numPlazasVip, int capacidadCola) {
        this.plazasNormales = numPlazas;
        this.plazasVip = numPlazasVip;
        this.capacidadCola = capacidadCola;
        this.colaEspera = new LinkedList<>();
    }

    public synchronized boolean intentarAparcar(Coche coche) {
        if (coche.isVip()) {
            if (ocupadasNormales + ocupadasVip < plazasNormales + plazasVip) {
                if (ocupadasNormales < plazasNormales) {
                    ocupadasNormales++;
                } else {
                    ocupadasVip++;
                }
                return true;
            }
        } else {
            if (ocupadasNormales < plazasNormales) {
                ocupadasNormales++;
                return true;
            }
        }

        if (colaEspera.size() < capacidadCola) {
            colaEspera.add(coche);
            return false;
        }

        return false; // El coche se va porque no hay espacio en la cola
    }

    public synchronized void salir(Coche coche) {
        if (coche.isVip() && ocupadasVip > 0) {
            ocupadasVip--;
        } else if (ocupadasNormales > 0) {
            ocupadasNormales--;
        }

        if (!colaEspera.isEmpty()) {
            Coche siguiente = colaEspera.poll();
            intentarAparcar(siguiente);
        }
    }

    public int getOcupadasNormales() {
        return ocupadasNormales;
    }

    public int getOcupadasVip() {
        return ocupadasVip;
    }

    public int getColaEsperaSize() {
        return colaEspera.size();
    }
}
